import{_ as a,o as d,c as e,ah as r}from"./chunks/framework.DuX8SFU5.js";const u=JSON.parse('{"title":"Периферийные функции","description":"","frontmatter":{"title":"Периферийные функции"},"headers":[],"relativePath":"features.md","filePath":"features.md"}'),o={name:"features.md"};function n(c,t,i,h,s,l){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="периферииные-функции" tabindex="-1">Периферийные функции <a class="header-anchor" href="#периферииные-функции" aria-label="Permalink to &quot;Периферийные функции&quot;">​</a></h1><p>Функции прошивки, из которых собираются устройства: что делает каждая, на каких платах работает и через какие сообщения CAN доступна. Многие из них сначала отрабатывались на отдельных отладочных платах, а теперь собраны на <a href="./am_node_v2/">AM_NODE_V2</a> и <a href="./am_can_to_can_bridge/">AM_CAN_BRIDGE</a>. Все узлы работают по DroneCAN; параметры задаются через DroneCAN GUI и сохраняются в узле.</p><h2 id="сводка" tabindex="-1">Сводка <a class="header-anchor" href="#сводка" aria-label="Permalink to &quot;Сводка&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Функция</th><th>AM_NODE_V2 H7</th><th>AM_NODE_V2 F103</th><th>AM_CAN_BRIDGE</th><th>AM_CAN_LOGGER</th></tr></thead><tbody><tr><td><a href="#loads">Управление нагрузками</a></td><td>4 канала</td><td>4 канала</td><td>—</td><td>—</td></tr><tr><td><a href="#bypass">Bypass штатного управления</a></td><td>да</td><td>да, LOAD3 и LOAD4 общие</td><td>отключение входного сегмента</td><td>—</td></tr><tr><td><a href="#digital-inputs">Дискретные входы и питание датчиков</a></td><td>8 входов</td><td>4 входа</td><td>—</td><td>—</td></tr><tr><td><a href="#current-inputs">Токовые входы 4–20 мА</a></td><td>4 входа</td><td>4 входа</td><td>—</td><td>—</td></tr><tr><td><a href="#load-current">Измерение тока нагрузок</a></td><td>да</td><td>да</td><td>—</td><td>—</td></tr><tr><td><a href="#power-monitor">Мониторинг питания</a></td><td>да</td><td>да</td><td>да</td><td>—</td></tr><tr><td><a href="#analog-inputs">Аналоговые входы и джойстики</a></td><td>—</td><td>—</td><td>—</td><td>—</td></tr><tr><td><a href="#can-gateway">Шлюз CAN</a></td><td>—</td><td>—</td><td>в разработке</td><td>—</td></tr><tr><td><a href="#can-logging">Запись CAN-трафика</a></td><td>—</td><td>—</td><td>—</td><td>да</td></tr><tr><td><a href="#firmware-update">Обновление прошивки по CAN</a></td><td>да</td><td>да</td><td>в разработке</td><td>через USB</td></tr></tbody></table><h2 id="loads" tabindex="-1">Управление нагрузками <a class="header-anchor" href="#loads" aria-label="Permalink to &quot;Управление нагрузками {#loads}&quot;">​</a></h2><p>Четыре канала LOAD управляют электрогидроклапанами, маяками, сигнализаторами и драйверами приводов. Канал работает в режиме включения/выключения или ШИМ: частота задаётся параметром <code>loads.pwm_hz</code>, границы скважности для ненулевой команды — <code>loads.pwm_min_percent</code> и <code>loads.pwm_max_percent</code>.</p><table tabindex="0"><thead><tr><th>CAN</th><th>Сообщение</th></tr></thead><tbody><tr><td>Команда</td><td><code>uavcan.equipment.actuator.ArrayCommand</code>; каналу назначается номер актуатора <code>loads.aid_N</code>, <code>-1</code> отключает канал</td></tr><tr><td>Состояние</td><td><code>uavcan.equipment.actuator.Status</code></td></tr></tbody></table><p>Модуль ключа нагрузки с измерением тока сначала отрабатывался на отдельной отладочной плате, теперь на AM_NODE_V2 установлено четыре таких модуля.</p><h2 id="bypass" tabindex="-1">Bypass штатного управления <a class="header-anchor" href="#bypass" aria-label="Permalink to &quot;Bypass штатного управления {#bypass}&quot;">​</a></h2><p>Плата встраивается в разрыв штатной линии машины. Пока bypass включён, реле замыкает линию напрямую и машина работает так, как будто платы нет; когда bypass выключен, сигналом управляет плата. Реле нормально замкнутое: если плата обесточена, зависла, перезагружается или ещё не готова, bypass включён и штатное управление работает.</p><table tabindex="0"><thead><tr><th>Устройство</th><th>Что идёт в обход</th></tr></thead><tbody><tr><td>AM_NODE_V2</td><td>Аналоговая команда джойстика на клапан, по каналам LOAD; в исполнении F103 каналы LOAD3 и LOAD4 переключаются вместе</td></tr><tr><td>AM_CAN_BRIDGE</td><td>Входной сегмент CAN0 отключается от шлюза двумя релейными каскадами</td></tr></tbody></table><p>Состояние задаётся параметрами <code>bypass.bN</code>: <code>0</code> — плата управляет, <code>1</code> — bypass включён; параметр применяется без перезагрузки. Управление bypass командой по CAN в реальном времени запланировано: при потере связи и при перезапуске линия будет возвращаться в безопасное состояние с включённым bypass.</p><h2 id="digital-inputs" tabindex="-1">Дискретные входы и питание датчиков <a class="header-anchor" href="#digital-inputs" aria-label="Permalink to &quot;Дискретные входы и питание датчиков {#digital-inputs}&quot;">​</a></h2><p>Линии SENS обслуживают микросхемы MAX14906: одни читают выходы датчиков, другие подают датчикам питание. Поэтому плата может обесточить отдельный датчик, не трогая остальные, и отличает обесточенный датчик от разомкнутого; подача питания программно заменяет отдельное реле.</p><table tabindex="0"><thead><tr><th>Возможность</th><th>Параметр</th></tr></thead><tbody><tr><td>Тип входа PNP или NPN, без перезагрузки</td><td><code>max14906.sensN_in.type</code></td></tr><tr><td>Номер публикации состояния, <code>-1</code> отключает</td><td><code>max14906.sensN_in.hid</code></td></tr><tr><td>Питание датчика: не трогать, выключить, включить</td><td><code>max14906.sensN_out.mode</code></td></tr></tbody></table><p>Состояние публикуется в <code>uavcan.equipment.hardpoint.Status</code>: <code>1</code> — выход датчика проводит, <code>0</code> — не проводит, <code>65535</code> — измерение недоступно. Четырёхканальный модуль MAX14906 сначала работал на отдельной отладочной плате; на AM_NODE_V2 H7 стоят четыре микросхемы и восемь разъёмов SENS, в исполнении F103 используются четыре входа.</p><h2 id="current-inputs" tabindex="-1">Токовые входы 4–20 мА <a class="header-anchor" href="#current-inputs" aria-label="Permalink to &quot;Токовые входы 4–20 мА {#current-inputs}&quot;">​</a></h2><p>Входы C_SENS измеряют ток датчиков с выходом 4–20 мА через INA228 на шунте 2 Ом. Каждому входу назначается роль параметром <code>ina.c_sensN.role</code>: ток, давление или перемещение. Калибровка задаётся граничными токами датчика в миллиамперах и соответствующими физическими значениями.</p><table tabindex="0"><thead><tr><th>Роль</th><th>Сообщение</th></tr></thead><tbody><tr><td>Ток</td><td><code>uavcan.equipment.power.CircuitStatus</code></td></tr><tr><td>Давление</td><td><code>uavcan.equipment.air_data.StaticPressure</code>; публикует исправный вход с наименьшим номером, так как в сообщении нет номера датчика</td></tr><tr><td>Перемещение</td><td><code>uavcan.equipment.range_sensor.Measurement</code>, в метрах; номер датчика — номер входа минус один</td></tr></tbody></table><p>Каждый включённый вход опрашивается с частотой 10 Гц; отказ одного входа не останавливает остальные. Подробная настройка — в <a href="./am_node_v2/ina228">руководстве по INA228</a>. Прежние модули давления и длины на INA234 относятся к снятой с производства плате и в новых сборках не используются.</p><h2 id="load-current" tabindex="-1">Измерение тока нагрузок <a class="header-anchor" href="#load-current" aria-label="Permalink to &quot;Измерение тока нагрузок {#load-current}&quot;">​</a></h2><p>На каждом канале LOAD два измерителя INA228: ток выхода на нагрузку и ток входа ручной команды. По ним видно, что подала плата и что пришло от штатного органа управления.</p><table tabindex="0"><thead><tr><th>Параметр</th><th>Назначение</th></tr></thead><tbody><tr><td><code>ina.loadN.in.circuit_id</code>, <code>ina.loadN.out.circuit_id</code></td><td>Номер цепи в <code>CircuitStatus</code>; <code>-1</code> отключает публикацию</td></tr><tr><td><code>ina.load_shunt_uohm</code></td><td>Сопротивление шунтов нагрузки, по умолчанию 20 мОм</td></tr><tr><td><code>ina.current.filter_percent</code></td><td>Сглаживание тока, 100 — без фильтра</td></tr></tbody></table><p>Наличие напряжения на выходе не доказывает протекание тока: INA228 измеряет напряжение шины и падение на шунте раздельно.</p><h2 id="power-monitor" tabindex="-1">Мониторинг питания <a class="header-anchor" href="#power-monitor" aria-label="Permalink to &quot;Мониторинг питания {#power-monitor}&quot;">​</a></h2><p>Узлы публикуют в <code>uavcan.equipment.power.CircuitStatus</code> входное напряжение, ток питания и напряжение шины 5 В, а также температуру. Набор публикаций и проверки на перенапряжение, недонапряжение, перегрузку по току и перегрев включаются параметром <code>crct.bitmask</code>. AM_CAN_BRIDGE дополнительно сообщает, от какого источника он питается: основного или USB.</p><h2 id="analog-inputs" tabindex="-1">Аналоговые входы и джойстики <a class="header-anchor" href="#analog-inputs" aria-label="Permalink to &quot;Аналоговые входы и джойстики {#analog-inputs}&quot;">​</a></h2><p>Чтение аналоговых джойстиков и операторских кнопок через 8-канальный АЦП TLA2528 отрабатывалось на отладочной плате: прошивка публиковала напряжения в <code>CircuitStatus</code> и рассчитанные из положения джойстика команды в <code>ArrayCommand</code>. На AM_NODE_V2 этой микросхемы нет; аналоговые сигналы подключаются через преобразователь в 4–20 мА на входы C_SENS.</p><h2 id="can-gateway" tabindex="-1">Шлюз CAN <a class="header-anchor" href="#can-gateway" aria-label="Permalink to &quot;Шлюз CAN {#can-gateway}&quot;">​</a></h2><p>AM_CAN_BRIDGE делит штатную CAN-линию на два сегмента и пересылает кадры программно: без изменений, с фильтрацией, с заменой выбранных значений или формируя сообщения отсутствующего штатного узла. Бортовой компьютер подключается по Ethernet или по отдельной шине CAN2. Подробности — на странице <a href="./am_can_to_can_bridge/">AM_CAN_BRIDGE</a>.</p><h2 id="can-logging" tabindex="-1">Запись CAN-трафика <a class="header-anchor" href="#can-logging" aria-label="Permalink to &quot;Запись CAN-трафика {#can-logging}&quot;">​</a></h2><p>AM_CAN_LOGGER записывает до двух CAN-шин машины и вибрации на карту памяти, не передавая ничего в шины. Подробности — на странице <a href="./am_can_logger/">AM_CAN_LOGGER</a>.</p><h2 id="firmware-update" tabindex="-1">Обновление прошивки по CAN <a class="header-anchor" href="#firmware-update" aria-label="Permalink to &quot;Обновление прошивки по CAN {#firmware-update}&quot;">​</a></h2><p>Узлы обновляются через загрузчик по CAN из GUI-инструмента, см. <a href="./firmware_update">Обновление прошивки</a>. Если в новой версии меняется таблица параметров, перед обновлением настройки сохраняются, а после него выполняется <strong>Erase All</strong> и настройки восстанавливаются по именам.</p>',34)])])}const _=a(o,[["render",n]]);export{u as __pageData,_ as default};
